                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            objs.append((color, cells))

    colors = []
    for color, _ in objs:
        if color not in colors:
            colors.append(color)

    out = [[0] * w for _ in range(h)]
    for ci, color in enumerate(colors):
        group = [cells for col, cells in objs if col == color]
        group.sort(key=lambda cells: min(r for r, c in cells))
        # Separate the two colors into left and right stacks; preserve object
        # shapes while placing the upper source object above the lower one.
        base_c = 0 if ci == 0 else 5
        for i, cells in enumerate(group):
            mr = min(r for r, c in cells)
            mc = min(c for r, c in cells)
            shape = [(r - mr, c - mc) for r, c in cells]
            base_r = 5 if i == 0 else 8
            for dr, dc in shape:
                rr, cc = base_r + dr, base_c + dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = color
    return out
